const ISO_DATE_PAD_LENGTH = 2;
const START_OF_DAY = 'T00:00:00';

@Injectable()
export class SlotsService {
  constructor(private readonly manager: EntityManager) {}

  async getSlots(): Promise<ResourceSlotsDto[]> {
    const [resources, slots, dependencies] = await Promise.all([
      this.manager.find(Resource, { order: { id: 'ASC' } }),
      this.manager.find(Slot, { order: { id: 'ASC' } }),
      this.manager.find(BlockingDependency),
    ]);

    const todaySlots = this.filterTodaysSlots(slots);
    const blockingIdsByResource = this.buildBlockingIdsByResource(dependencies);

    return resources.map((resource) => {
      const blockingIds = blockingIdsByResource.get(resource.id) ?? new Set();
      const relevantSlots = todaySlots.filter(
        (slot) =>
          slot.resourceId === resource.id || blockingIds.has(slot.resourceId),
      );

      return {
        resourceId: resource.id,
        slots: relevantSlots.map((slot) =>
          this.toSlotDto(
            slot,
            this.findConflicts(slot, todaySlots, blockingIdsByResource),
          ),
        ),
      };
    });
  }

    return {
      ...slot,
      conflicts: [],
    };
  }

  /**
   * Includes slots that start today and overnight slots that started yesterday
   * and end today.
   */
  private filterTodaysSlots(slots: Slot[]): Slot[] {
    const now = new Date();
    const todayStart = `${this.formatLocalDate(now)}${START_OF_DAY}`;
    const tomorrow = new Date(now);
    tomorrow.setDate(tomorrow.getDate() + 1);
    const tomorrowStart = `${this.formatLocalDate(tomorrow)}${START_OF_DAY}`;

    return slots.filter(
      (slot) => slot.start < tomorrowStart && slot.end > todayStart,
    );
  }

  private formatLocalDate(date: Date): string {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(
      ISO_DATE_PAD_LENGTH,
      '0',
    );
    const day = String(date.getDate()).padStart(ISO_DATE_PAD_LENGTH, '0');
    return `${year}-${month}-${day}`;
  }

  /**
   * Maps each resource to the set of resource IDs that block it.
   */
  private buildBlockingIdsByResource(
    dependencies: BlockingDependency[],
  ): Map<number, Set<number>> {
    const blockingIdsByResource = new Map<number, Set<number>>();

    for (const dependency of dependencies) {
      let blockingIds = blockingIdsByResource.get(dependency.blockedResourceId);
      if (!blockingIds) {
        blockingIds = new Set();
        blockingIdsByResource.set(dependency.blockedResourceId, blockingIds);
      }
      blockingIds.add(dependency.blockingResourceId);
    }

    return blockingIdsByResource;
  }

  /**
   * A conflict is an overlapping slot on the same resource or on a resource
   * that blocks this slot's resource.
   */
  private findConflicts(
    slot: Slot,
    allSlots: Slot[],
    blockingIdsByResource: Map<number, Set<number>>,
  ): SlotDto[] {
    const blockingIds = blockingIdsByResource.get(slot.resourceId) ?? new Set();

    return allSlots
      .filter(
        (other) =>
          other.id !== slot.id &&
          this.slotsOverlap(slot, other) &&
          (other.resourceId === slot.resourceId ||
            blockingIds.has(other.resourceId)),
      )
      .map((other) => this.toSlotDto(other));
  }

  private slotsOverlap(
    a: Pick<Slot, 'start' | 'end'>,
    b: Pick<Slot, 'start' | 'end'>,
  ): boolean {
    return a.start < b.end && a.end > b.start;
  }

  private toSlotDto(slot: Slot, conflicts: SlotDto[] = []): SlotDto {
    return {
      id: slot.id,
      name: slot.name,
      start: slot.start,
      end: slot.end,
      resourceId: slot.resourceId,
      conflicts,
    };
  }
}

